/**
 * HTTP Transport for OneSource Docs MCP Server
 *
 * Stateless Streamable HTTP — creates a fresh server + transport per request.
 * Content is loaded once at startup and reused across requests.
 * Run directly: `node dist/http-server.js`
 * Or via CLI: `onesource-docs-mcp --http`
 */
import { createServer } from 'node:http';
import { createRequire } from 'node:module';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import { createMcpServer, loadData } from './create-server.js';
const require = createRequire(import.meta.url);
const VERSION = require('../package.json').version;
// Pre-load content once at startup instead of per-request
const preloaded = loadData();
function setCorsHeaders(res) {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, mcp-session-id');
}
async function handleRequest(req, res) {
    setCorsHeaders(res);
    // CORS preflight
    if (req.method === 'OPTIONS') {
        res.writeHead(204).end();
        return;
    }
    // Health check
    if (req.method === 'GET' && req.url === '/health') {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'ok', server: 'onesource-docs-mcp', version: VERSION }));
        return;
    }
    // MCP only accepts POST (stateless mode)
    if (req.method !== 'POST') {
        res.writeHead(405, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
            jsonrpc: '2.0',
            error: { code: -32000, message: 'Method not allowed.' },
            id: null,
        }));
        return;
    }
    const server = createMcpServer(preloaded);
    const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined });
    // Register cleanup before handleRequest so it runs even if handleRequest throws
    res.on('close', () => {
        transport.close();
        server.close();
    });
    try {
        await server.connect(transport);
        await transport.handleRequest(req, res);
    }
    catch (error) {
        console.error('[onesource-docs] Request error:', error);
        if (!res.headersSent) {
            res.writeHead(500, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                jsonrpc: '2.0',
                error: { code: -32603, message: 'Internal server error' },
                id: null,
            }));
        }
    }
}
const PORT = parseInt(process.env.PORT ?? '3001', 10);
const httpServer = createServer(handleRequest);
httpServer.listen(PORT, () => {
    console.error(`[onesource-docs] MCP HTTP server listening on http://localhost:${PORT}/mcp`);
    console.error(`[onesource-docs] Health check: http://localhost:${PORT}/health`);
});
process.on('SIGINT', () => {
    console.error('[onesource-docs] Shutting down...');
    httpServer.close();
    process.exit(0);
});
